import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_data_line(s: str) -> bool:
        t = s.strip()
        if not t:
            return False
        if t.startswith("DATE,") or t.startswith("DATE;"):
            return True
        if re.match(r"^\d{1,2}/\d{1,2}/\d{4},", t):
            return True
        return False

    start = 0
    while start < len(lines) and not is_data_line(lines[start]):
        start += 1

    if start >= len(lines):
        return {"columns": [], "rows": []}

    data_text = "\n".join(lines[start:])
    reader = csv.reader(io.StringIO(data_text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
    rows = []
    for row in reader:
        if not row:
            continue
        rows.append([str(v) for v in row])

    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    data_rows = rows[1:]

    width = len(header)
    normalized = []
    for row in data_rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        normalized.append(row)

    return {"columns": header, "rows": normalized}
